                    <div className="w-10 h-10 bg-purple-100 rounded-lg flex items-center justify-center">
                      <Box className="w-5 h-5 text-purple-600" />
                    </div>
                    <div>
                      <h3 className="font-semibold text-foreground">{model.name}</h3>
